CREATE TABLE IF NOT EXISTS gis_phase339_intersection_evidence (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), crosswalk_version TEXT NOT NULL, candidate_id UUID NOT NULL, source_feature_id UUID NOT NULL, target_feature_id UUID NOT NULL, source_area DOUBLE PRECISION, target_area DOUBLE PRECISION, intersection_area DOUBLE PRECISION, source_overlap_ratio DOUBLE PRECISION, target_overlap_ratio DOUBLE PRECISION, iou DOUBLE PRECISION, method TEXT NOT NULL DEFAULT 'geojson_bbox_planar', evidence JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(crosswalk_version,candidate_id));